  const [ruleSearch, setRuleSearch] = useState("");
  const [testText, setTestText] = useState("");
  const [testSurface, setTestSurface] = useState<"posts" | "comments" | "messages" | "profiles">("messages");
  const [testRun, setTestRun] = useState(false);
  const [reviewQueue, setReviewQueue] = useState<"all" | "moderation" | "verification" | "support" | "incident" | "agent_review">("all");
  const [newRuleName, setNewRuleName] = useState("");
  const [newRulePattern, setNewRulePattern] = useState("");
  const [newRuleType, setNewRuleType] = useState<"bad_word" | "phone_number" | "link_domain" | "spam" | "personal_data" | "threat" | "scam">("bad_word");
  const [newDomain, setNewDomain] = useState("");
  const [newDomainSeverity, setNewDomainSeverity] = useState<"low" | "medium" | "high" | "critical">("high");
  const [communityEligibility, setCommunityEligibility] = useState("");
  const [editingCommunityId, setEditingCommunityId] = useState<number | null>(null);
  const [editingCommunityEligibility, setEditingCommunityEligibility] = useState("");
