  const [selectedIncidentId, setSelectedIncidentId] = useState<number | null>(null);
  const [supportCategory, setSupportCategory] = useState("safety");
  const [supportSummary, setSupportSummary] = useState("");
  const [supportOwnerId, setSupportOwnerId] = useState("");
  const [supportSlaDueAt, setSupportSlaDueAt] = useState("");
  const [incidentType, setIncidentType] = useState("unsafe_meeting");
  const [incidentSummary, setIncidentSummary] = useState("");
  const [incidentEvidenceReference, setIncidentEvidenceReference] = useState("");
  const [verificationResubmissionReason, setVerificationResubmissionReason] = useState("");
  const [verificationProvider, setVerificationProvider] = useState("");
  const [verificationOutcome, setVerificationOutcome] = useState("");
  const [verificationAppealNotes, setVerificationAppealNotes] = useState("");
  const [evidenceType, setEvidenceType] = useState("case_context");
  const [evidenceReference, setEvidenceReference] = useState("");
  const [editingRuleId, setEditingRuleId] = useState<number | null>(null);
  const [editingRuleName, setEditingRuleName] = useState("");
  const [editingRulePattern, setEditingRulePattern] = useState("");
  const isAdmin = Boolean(isAuthenticated && user?.role === "admin");
  const queryOptions = { enabled: isAdmin };
