  const setRuleStatusMutation = trpc.operations.setSafetyRuleStatus.useMutation({ onSuccess: () => rules.refetch() });
  const setDomainStatusMutation = trpc.operations.setBlockedDomainStatus.useMutation({ onSuccess: () => blockedDomains.refetch() });
  const setCommunityStatusMutation = trpc.operations.setCommunityStatus.useMutation({ onSuccess: () => { communities.refetch(); overview.refetch(); } });
